nta.declaration:
// Biodiesel reactor
const double DT = 0.01;
const double TARGET = 0.99;

clock t;
hybrid clock x_e = 0.0;      // ester fraction
hybrid clock x_tg = 1.0;     // triglyceride fraction
hybrid clock temp = 300.0;   // K
hybrid clock heater = 1.0;   // 1.0 on, 0.0 off
bool reached = false;

double r1() { return 40000.0 * exp(-5000.0 / temp) * x_tg * (1.0 - x_e); }
double r2() { return 2000.0 * exp(-5500.0 / temp) * x_tg * x_tg; }
double heat() { return heater > 0.5 ? 500.0 * (350.0 - temp) : 10.0 * (298.0 - temp); }

void step() {
    double dr1 = r1();
    double dr2 = r2();
    double dh = heat();
    if (random(1.0) < 0.0002) heater = 0.0;
    temp = temp + (0.05 * dh + 10.0 * dr1) * DT;
    x_tg = (x_tg + (-dr1 - dr2) * DT < 0.0) ? 0.0 : x_tg + (-dr1 - dr2) * DT;
    x_e = (x_e + 3.0 * dr1 * DT < 0.0) ? 0.0 : x_e + 3.0 * dr1 * DT;
    if (x_e >= TARGET) reached = true;
}
